package org.sleepwell.app;
import android.app.Activity;import android.os.Bundle;import android.graphics.*;import android.view.View;import android.widget.*;import org.json.JSONObject;import java.util.*;import java.util.concurrent.*;
/** Real saved secondary hub states; never interpolates a clear/motion interval. */
public final class PirReportActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private int generation;private RecordEntry record;private JSONObject run;private List<JSONObject> samples=List.of();private String error="";
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);}
 @Override protected void onResume(){super.onResume();load();}
 private void load(){int request=++generation;long id=getIntent().getLongExtra("record",0);Records.Factory factory=Records.factory;error="";LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Recorded PIR states",this::finish);Design.text(body,"Opening saved hub evidence…",14,400,Design.MUTED);worker.execute(()->{try(Store store=factory.open(getApplicationContext())){RecordEntry entry=Records.get(store,id);List<JSONObject> runs=store.rows("SELECT policy,state,error FROM pir_runs WHERE session=?",Long.toString(id));List<JSONObject> data=store.rows("SELECT time,elapsed_ms,state,quality,age_ms,latency_ms FROM pir_samples WHERE session=? ORDER BY time LIMIT 10001",Long.toString(id));if(data.size()>10000)throw new IllegalStateException("This PIR history exceeds the view limit. Saved data is kept.");runOnUiThread(()->{if(isDestroyed()||request!=generation)return;record=entry;run=runs.isEmpty()?null:runs.get(0);samples=data;render();});}catch(Exception failure){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;error="PIR evidence could not be opened. Saved records are kept.";render();});}});}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Recorded PIR states",this::finish);Design.space(body,12);if(!error.isEmpty()){Design.text(body,error,15,500,Design.BROWN);Design.button(body,"Try again",true,this::load);return;}if(record==null)return;Design.text(body,RecordUi.date(record.edit.end,record.zone()),14,400,Design.MUTED);if(run==null){Design.space(body,16);Design.text(body,"Not recorded / legacy unknown",21,600,Design.INK);Design.text(body,"This night has no PIR provenance. No clear or motion state is inferred.",14,400,Design.MUTED);return;}String state=run.optString("state");Design.text(body,state.equals("off")?"Off for this night":"Outcome: "+state,19,600,Design.INK);if(!run.optString("error").isEmpty())Design.text(body,"Saved error: "+run.optString("error"),13,500,Design.BROWN);if(state.equals("off"))return;try{String policy=run.optString("policy");if(!policy.isEmpty()){PirConfig.validatePolicy(policy);JSONObject p=new JSONObject(policy);Design.text(body,"Home Assistant "+p.getString("device_class")+" · on-change hub snapshots",13,500,Design.MUTED);}}catch(Exception invalid){Design.text(body,"Saved method metadata unavailable.",13,500,Design.BROWN);}List<JSONObject> visible=new ArrayList<>();int motion=0,clear=0,unknown=0;for(JSONObject sample:samples){long time=sample.optLong("time");if(time<record.edit.start||time>record.edit.end)continue;visible.add(sample);if(sample.isNull("state"))unknown++;else if(sample.optInt("state")==1)motion++;else clear++;}Design.space(body,14);Design.text(body,motion+" motion/occupied · "+clear+" clear · "+unknown+" unknown snapshots",15,600,Design.INK);Design.space(body,10);body.addView(new Chart(visible,record.edit.start,record.edit.end),new LinearLayout.LayoutParams(-1,Design.dp(this,176)));Design.text(body,"Each mark is one actual saved hub response. No lines connect points; blank space is unknown/unpolled, including pauses. State is not held between polls.",12,400,Design.MUTED);Design.space(body,12);Design.text(body,"The hub may retain an unchanged state for hours. Update age is not hardware freshness. PIR placement, other people, pets, network loss and hub caching affect these snapshots. They do not determine your body movement, awake time or sleep stages and do not alter recorded duration.",13,400,Design.MUTED);RecordUi.heading(body,"Recent saved responses");int from=Math.max(0,visible.size()-30);for(int n=visible.size()-1;n>=from;n--){JSONObject row=visible.get(n);String value=row.isNull("state")?"Unknown":row.optInt("state")==1?"Motion / occupied":"Clear";Design.text(body,RecordUi.clock(this,row.optLong("time"),record.zone())+" · "+value+" · "+row.optString("quality"),13,500,Design.INK);Design.text(body,(row.isNull("age_ms")?"Update age unknown":"Hub update age "+RecordUi.duration(row.optLong("age_ms")))+(row.optString("quality").equals("UNAVAILABLE")?" · request failed; latency unavailable":" · request "+row.optLong("latency_ms")+" ms"),11,400,Design.MUTED);Design.space(body,8);}if(visible.isEmpty())Design.text(body,"No saved responses inside this edited period. No clear state is assumed.",14,400,Design.MUTED);if(visible.size()>30)Design.text(body,"Showing latest 30 responses; all "+visible.size()+" visible points are plotted above.",12,400,Design.MUTED);Design.button(body,"External PIR settings",false,()->startActivity(RecordUi.intent(this,PirSettingsActivity.class)));}
 private final class Chart extends View {final List<JSONObject> rows;final long start,end;final Paint paint=new Paint(3);Chart(List<JSONObject> rows,long start,long end){super(PirReportActivity.this);this.rows=rows;this.start=start;this.end=end;setContentDescription("Discrete saved PIR hub states: top motion or occupied, middle unknown, bottom clear. Missing times stay blank.");}protected void onDraw(Canvas canvas){super.onDraw(canvas);float left=Design.dp(getContext(),45),right=getWidth()-Design.dp(getContext(),7),top=Design.dp(getContext(),24),bottom=getHeight()-Design.dp(getContext(),20);paint.setTypeface(Design.font(getContext(),400));paint.setTextSize(Design.dp(getContext(),10));paint.setColor(Design.MUTED);canvas.drawText("Motion",0,top+4,paint);canvas.drawText("?",0,(top+bottom)/2+4,paint);canvas.drawText("Clear",0,bottom+4,paint);paint.setColor(Design.LINE);canvas.drawLine(left,top,right,top,paint);canvas.drawLine(left,bottom,right,bottom,paint);long width=Math.max(1,end-start);for(JSONObject row:rows){float x=left+(right-left)*(row.optLong("time")-start)/(float)width;boolean unknown=row.isNull("state");float y=unknown?(top+bottom)/2:row.optInt("state")==1?top:bottom;paint.setColor(unknown?Design.MUTED:row.optInt("state")==1?Design.BROWN:Design.VIOLET);canvas.drawCircle(x,y,Design.dp(getContext(),2),paint);}}}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
